"""Reading aids for the original Paper XI vector artwork and retained finite data."""
DESCRIPTIONS={
 '01_three_objects':('Weil atoms, monodromy chains, finite comparison, and arithmetic realization','Four boxes distinguish Weil atoms, monodromy chains, finite packet comparison, and actual arithmetic realization. The horizontal arrow from finite comparison to arithmetic realization is marked conjectural. Finite comparison does not create the arithmetic witness.'),
 '02_monodromy':('A five-term monodromy chain','Five spaces run from V zero to V four. The arrows for N point toward the preceding space. A path of five transfers cannot exist, giving the illustrated nilpotence statement.'),
 '03_tame_orbit':('Multiplication by two around a tame orbit modulo fifteen','The four labels 1, 2, 4 and 8 form a cycle under multiplication by two modulo fifteen. The arrows encode the fixed geometric Frobenius convention.'),
 '04_orbit_counts':('Exact regular Frobenius orbit counts','Three series give regular orbit counts for residue sizes two, three and five, at orbit lengths one through eight. The vertical axis is logarithmic. The following table retains the recorded integers.'),
 '05_tensor_grid':('Two diagonal orbits on a four by six grid','Rows are coordinates modulo four and columns coordinates modulo six. Each cell is labelled zero or one. Simultaneous translation preserves that label and partitions the grid into two orbits of twelve cells.'),
 '06_cycle_scalar':('A cyclic chain with a distinguished closing scalar','A four-step cycle has ordinary transfer edges and one closing edge marked a. Its characteristic polynomial is X to the fourth minus a. The closing scalar retains information beyond the inertia orbit.'),
 '07_heisenberg':('Translations and multipliers generate a Heisenberg packet','Translation and multiplication operators feed a common representation space. Their noncommutation is the central scalar relation; together they generate the full matrix algebra in the supplied finite model.'),
 '08_radical':('Radical directions and a nondegenerate quotient','A projective commutator space passes to its quotient by the radical. Radical directions commute with every generator; the remaining quotient carries the nondegenerate alternating form.'),
 '09_bridge':('Two supplied finite models compared by a bridge','The two representations are related by a supplied intertwiner. Their remaining discrepancy is a scalar character, which a cyclic generator phase can remove under the stated assumptions.'),
 '10_quadratic_planes':('Two quadratic refinements of the same symplectic plane','Two four-point diagrams share the underlying alternating plane but assign different quadratic values. The retained point table records the two refinements and distinguishes their signs.'),
 '11_arf_counts':('Counts of refinements of Arf invariant zero and one','Paired bars show the two Arf counts in dimensions two through ten, indexed by half dimension one through five. The vertical scale is logarithmic; the table retains each exact count.'),
 '12_holonomy':('A spanning tree and two cycle-testing chords','Vertices r, u, v and w are connected by solid tree edges and dashed extra edges. The tree fixes vertex gauges; each extra edge closes a cycle whose residual must be checked.'),
 '13_break_tensor':('An orthogonal sum becomes a tensor factorization','Three break spaces and their representations appear above an orthogonal decomposition and its tensor-product representation. The source gives the hypotheses for that factorization.'),
 '14_recursive_parameter':('Native field, derived parameter, and ambient matrix','A native parameter field and a matrix over it feed an actual ambient matrix obtained by adding the scalar parameter to a lifted matrix. The diagram keeps the derived field separate from the final parameter field.'),
 '15_degree_levels':('Two recorded approximation-degree and critical-level profiles','The dyadic example uses degrees two, four and eight with levels sixty, eighteen and three. The odd example uses degrees three, nine and twenty-seven with levels one hundred forty-four, twenty-four and four. These are finite illustrative profiles.'),
 '16_scalar_depth':('Odd trace zero and dyadic trace one satisfy a depth condition','The odd tower has native trace zero; the dyadic tower has native trace one. Both feed a depth inequality ensuring the displayed additive character is trivial on the required scalar perturbations.'),
 '17_native_ambient_trace':('Native trace one can amplify to ambient trace zero','Native ranks two, four and eight each have trace one. In ambient rank eight their traces are zero, zero and one. Native trace and amplified ambient trace have different roles.'),
 '18_capacity':('Original quotient and whole-source symplectic dimensions','Paired bars compare original quotient dimension N minus two with whole-source dimension twice d, for N equal to two to the d and d from one through five. The data table separately records representation carrier dimensions.'),
 '19_enlarged_carrier':('An enlarged compact carrier recovers the same candidate','The original compact type maps to an enlarged compact group of index two. Both lead to the same supercuspidal candidate. The enlargement changes the assembly carrier while retaining the inducing representation.'),
 '20_induction_stages':('Induction in stages between two noncompact groups','The upper row enlarges K times J to K times P. The lower row induces Lambda to Sigma. Compact induction of Sigma recovers the displayed same candidate.'),
 '21_marked_extension':('The whole marked finite subgroup travels through the map','An arrow carries a marked source extension, including lifts and squares, into a scalar pushout. The square identity is preserved. An independently prescribed native marking needs its own comparison.'),
 '22_completion':('Finite packet and noncompact completion determine one candidate','A finite compact packet and a noncompact central-character and root choice feed one actual candidate with an arithmetic recovery witness. Completion is additional construction data.'),
 '23_conjecture_boundary':('Conjectural existence and conditional same-candidate comparison','The upper arrow from supplied H1 through H4 data to an arithmetic witness is labelled Conjecture 66. The witness and H5 for that same candidate feed the lower conditional comparison. The diagram does not provide the missing general existence witness.')
}


def data_tables(name,data):
    table=lambda caption,headers,rows:dict(caption=caption,headers=headers,rows=rows)
    if name=='04_orbit_counts':return [table('Recorded exact regular orbit counts',['Orbit length n','q = 2','q = 3','q = 5'],[[i+1,*values] for i,values in enumerate(zip(*(data['orbit_counts'][q] for q in ['2','3','5'])))])]
    if name=='05_tensor_grid':return [table('Recorded diagonal orbit labels',['Coordinate mod 4',*['Column '+str(i) for i in range(6)]],[[i,*row] for i,row in enumerate(data['tensor_4_6'])])]
    if name=='10_quadratic_planes':return [table('Recorded quadratic values',['Point (x, y)','q0','q1'],[[str((r['x'],r['y'])),r['q0'],r['q1']] for r in data['quadratic_planes']])]
    if name=='11_arf_counts':return [table('Recorded counts by Arf invariant',['Half dimension r','Arf 0','Arf 1'],[[r['r'],r['zero'],r['one']] for r in data['arf_counts']])]
    if name=='15_degree_levels':return [table('Recorded critical levels',['Stage','Dyadic level','Odd p = 3 level'],[[i+1,*values] for i,values in enumerate(zip(data['levels']['dyadic'],data['levels']['odd_p3']))])]
    if name=='18_capacity':return [table('Recorded quotient and carrier dimensions',['d','Ambient rank','Host symplectic dimension','Source symplectic dimension','Host representation dimension','Source representation dimension'],[[r[k] for k in ('d','rank','host_symplectic','source_symplectic','host_carrier','source_carrier')] for r in data['dyadic_capacity']])]
    return []
